"""Create a small portable online installer from an explicit public allowlist."""
from pathlib import Path
import argparse, hashlib, json, zipfile

ROOT=Path(__file__).parent
NAMES=('Update.ps1','Online-Core.psm1','Language.psm1')
GUIDE='TGC - Anime Total Overhaul (Korean) — 온라인 설치·업데이트\n\nZIP 전체를 압축 해제하고 게임과 런처를 종료한 뒤 Update.cmd를 실행하세요.\n처음에는 Victoria II 설치 폴더의 v2game.exe를 선택합니다. 설치 언어를 선택하고,\n런처에서 해당 언어의 TGC - Anime Total Overhaul과 TGO - The Grand Orchestra를\n함께 선택하세요. 게임은 자동 실행하지 않습니다.\n\n이미 설치한 PC도 같은 Update.cmd를 사용합니다. Check-Updates.cmd는 변경 여부를\n확인하고, Change-Language.cmd는 한국어 / English를 변경합니다. 언어 선택은\n업데이트 후에도 유지되며 언어 변경에도 인터넷 연결이 필요합니다.\n\n모드·캐시·DLL·런처는 백업 없이 최신 파일로 덮어씁니다. TGCNV/TGO 폴더와 지도\n캐시의 이전 파일 및 개인 수정은 제거됩니다. 세이브와 개인 설정은 유지합니다.\n이전 상태로 자동 복원할 수 없습니다. 설치 중단 시 같은 Update.cmd를 다시 실행하세요.\nRestore-Update.cmd는 이 안내만 표시하며 복원을 실행하지 않습니다.\ntgcnv_lua51_ori.dll은 엔진 실행에 필요한 원본 Lua 의존 파일이므로 삭제하지 마세요.\n이는 이전 모드 버전의 백업이 아닙니다. 과거 설치기가 만든 기존 백업은 자동 삭제하지 않습니다.\n\nRelease에서는 인스톨러만 받으며 실제 파일은 공개 GitHub Packages(GHCR)에서 받습니다.\n처음에는 전체 파일이 필요하고 이후에는 해시를 비교해 변경된 파일이 든 묶음만 받습니다.\n화면에 최대 다운로드 용량이 표시됩니다. RSA 서명·크기·SHA-256을 확인한 뒤 설치합니다.\n다운로드가 끊겼으면 다시 실행하세요. 검증 실패 시 게임 파일을 교체하지 않습니다.\n설치 시 새 파일을 임시로 준비하므로 전체 새 파일을 풀 공간이 필요합니다.\n임시 설치 파일은 종료 시 정리하며, 해시가 확인된 다운로드 캐시는 재사용합니다.\n다운로드 캐시: %LOCALAPPDATA%\\TGCNV-Updater\n작은 현재 설치 기록: 게임 폴더의 TGCNV_Install\\receipt.json\n\n지원되는 정품 Victoria II/DLC, 64비트 Windows, Windows PowerShell 5.1 및 GitHub·ghcr.io\n인터넷 연결이 필요합니다. 받는 PC에 Python, Git, Docker, GitHub 계정은 필요 없습니다.\n문서 폴더가 다른 위치라면 다음처럼 실행합니다.\nUpdate.cmd -GamePath "D:\\Games\\Victoria 2" -DocumentsPath "D:\\Documents"\n권한 오류가 있으면 현재 Windows 계정에서 관리자 권한으로 실행하세요.\n다른 계정으로 실행하면 문서 경로와 다운로드 캐시가 달라질 수 있습니다.\n\n설치기 자체는 자동 교체하지 않습니다. 새 설치기가 안내되면 공식 ZIP을 다시 받으세요.\n기존 온라인 설치기는 새 설치 스크립트를 받더라도 예전 백업 안내를 표시할 수 있습니다.\n이 새 ZIP을 사용하면 백업 없는 덮어쓰기 안내와 임시 파일 정리가 함께 적용됩니다.\n개인 설정·세이브·GitHub 인증값은 서버로 전송하지 않습니다.\n새 엔진과 기존 세이브의 호환성을 보증하지 않으므로 해당 배포 안내를 확인하세요.\n\n저장소: https://github.com/Yukino-Chan/TGC-Anime-Total-Overhaul-Korean\n원본 TGC: https://github.com/The-Grand-Combination/The-Grand-Combo\nTGO: https://github.com/The-Grand-Combination/The-Grand-Orchestra\n모드와 음악의 제작자·출처는 각 모드 문서를 확인하세요.\n'
ENGLISH_GUIDE='TGC - Anime Total Overhaul — Online installer\n\nExtract the entire ZIP, close Victoria II and its launcher, then run Update.cmd.\nSelect v2game.exe in your supported Victoria II installation and choose Korean or\nEnglish. Select the matching TGC - Anime Total Overhaul entry and TGO - The Grand\nOrchestra in the launcher. Keep the base game language set to English. The installer\ndoes not launch or terminate the game.\n\nRun Update.cmd again to update. Check-Updates.cmd checks for changes without\ninstalling. Change-Language.cmd changes the language; your choice persists across\nupdates. Language changes also use the signed online feed and require internet.\nCommand-line example: Update.cmd -Language en\nFor relocated documents: Update.cmd -GamePath "D:\\Games\\Victoria 2" -DocumentsPath "D:\\Documents"\n\nInstallation OVERWRITES the managed mods, map cache, DLLs and launcher without\ncreating old-version backups. Obsolete files and personal edits inside TGCNV/TGO\nand their map cache are removed. Saves and personal settings are preserved.\nThere is no automatic rollback. If installation is interrupted, rerun the same\nUpdate.cmd to finish. Restore-Update.cmd only explains this policy; it cannot\nrestore an earlier version. Existing backups from older installers are untouched.\nDo not delete tgcnv_lua51_ori.dll: the engine needs this original Lua dependency\nat runtime. It is not a saved copy of a previous mod installation.\n\nThe GitHub Release contains only this installer. Signed manifests and patch data\nare downloaded from public GitHub Packages (GHCR). The first install requires the\nfull data; later updates reuse matching files and download only the archives that\ncontain missing or changed files. The maximum download size is shown beforehand.\nRSA signatures, file sizes and SHA-256 hashes are checked before installation.\nIf downloading or verification fails, installed game files are left untouched.\n\nAllow enough free space for temporary incoming files. Temporary installation\nfiles are cleaned up when the installer exits. Verified download objects are\ncached in %LOCALAPPDATA%\\TGCNV-Updater for subsequent runs. A small current\ninstallation receipt is kept at TGCNV_Install\\receipt.json in the game folder.\n\nRequires a supported genuine Victoria II/DLC installation, 64-bit Windows,\nWindows PowerShell 5.1, and access to github.com and ghcr.io. No Python, Git,\nDocker or GitHub account is needed. For write-permission errors, elevate using\nthe same Windows account so the documents directory does not change.\n\nThe updater itself is not automatically replaced. Download the new official ZIP\nwhen advised, including this overwrite-only revision. Older updater windows may\nstill describe backups even when the downloaded Setup script no longer makes them.\nSave compatibility depends on the release; consult its notes before loading an\nold campaign. Private settings, saves and authentication secrets are never uploaded.\n\nProject: https://github.com/Yukino-Chan/TGC-Anime-Total-Overhaul-Korean\nUpstream: https://github.com/The-Grand-Combination/The-Grand-Combo\nMusic: https://github.com/The-Grand-Combination/The-Grand-Orchestra\nOriginal creator credits and music sources remain in the mod documentation.\n'

def build(trust_path,output):
    trust=Path(trust_path).read_bytes()
    t=json.loads(trust)
    if '<D>' in t['public_key_xml'] or t['repository']!='Yukino-Chan/TGC-Anime-Total-Overhaul-Korean': raise ValueError('Invalid public trust config')
    files={name:(ROOT/name).read_bytes() for name in NAMES}
    for name,data in files.items():
        if b'TGCNV_QA_' in data or b'PRIVATE FIXTURE' in data: raise ValueError('Fixture code in client')
        if not data.startswith(b'\xef\xbb\xbf'): raise ValueError('PowerShell source needs UTF-8 BOM')
    for name,action in [('Update.cmd','Update'),('Check-Updates.cmd','Check'),('Restore-Update.cmd','Restore')]:
        files[name]=(f'@echo off\r\nsetlocal\r\n"%SystemRoot%\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -NoProfile -STA -ExecutionPolicy Bypass -File "%~dp0Update.ps1" -Action {action} %*\r\nset "result=%errorlevel%"\r\npause\r\nexit /b %result%\r\n').encode('ascii')
    files['Change-Language.cmd']=('@echo off\r\nsetlocal\r\n"%SystemRoot%\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -NoProfile -STA -ExecutionPolicy Bypass -File "%~dp0Update.ps1" -Action Update -ChooseLanguage %*\r\nset "result=%errorlevel%"\r\npause\r\nexit /b %result%\r\n').encode('ascii')
    files['trust.json']=trust
    files['온라인 설치 안내.txt']=(GUIDE+'\n언어 선택: 처음 설치할 때 한국어 / English를 선택합니다. 이후 업데이트에도 유지됩니다. 변경하려면 게임 종료 후 Change-Language.cmd를 실행하세요.\n명령줄: Update.cmd -Language en 또는 Update.cmd -Language ko\n').encode('utf-8-sig')
    files['README-English.txt']=ENGLISH_GUIDE.encode('utf-8')
    files['SHA256SUMS.txt']=''.join(f'{hashlib.sha256(data).hexdigest()}  {name}\n' for name,data in sorted(files.items())).encode('utf-8')
    output=Path(output)
    with zipfile.ZipFile(output,'w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for name,data in sorted(files.items()):
            info=zipfile.ZipInfo('TGC-Online-Installer/'+name,date_time=(2026,9,26,0,0,0))
            info.compress_type=zipfile.ZIP_DEFLATED
            z.writestr(info,data)
    with zipfile.ZipFile(output) as z:
        if z.testzip():raise ValueError('Client ZIP CRC')
        for name,data in files.items():
            if z.read('TGC-Online-Installer/'+name)!=data:raise ValueError('Client ZIP content')
    digest=hashlib.sha256(output.read_bytes()).hexdigest()
    output.with_suffix(output.suffix+'.sha256').write_text(digest+'  '+output.name+'\n',encoding='utf-8')
    return {'path':str(output),'sha256':digest,'bytes':output.stat().st_size}

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--trust',required=True);p.add_argument('--output',required=True)
    a=p.parse_args();print(json.dumps(build(a.trust,a.output)))
